// ═══ PER-ACCOUNT LOCK — different accounts in parallel! ═══
public class Account {
    private final String accountId;
    private final Object lock = new Object();  // per-account lock!
    private BigDecimal balance;

    public void debit(BigDecimal amount) {
        validateAmount(amount);         // NO lock — runs freely!
        synchronized (lock) {           // lock ONLY for balance modification!
            if (balance.compareTo(amount) < 0)
                throw new InsufficientFundsException(accountId, balance, amount);
            balance = balance.subtract(amount);
        }
        auditLog("DEBIT", amount);      // NO lock — runs freely!
    }

    public BigDecimal getBalance() {
        synchronized (lock) {
            return balance;
        }
    }
}
// Rajesh.debit() and Priya.debit() → DIFFERENT lock objects → PARALLEL!
// Two debits on Rajesh → SAME lock → serialized (safe!)

// ═══ TRANSFER BETWEEN ACCOUNTS — DEADLOCK PREVENTION ═══
public class TransferService {

    public void transfer(Account from, Account to, BigDecimal amount) {
        // ALWAYS lock in consistent order by account ID to prevent deadlock!
        Account first = from.getId().compareTo(to.getId()) < 0 ? from : to;
        Account second = first == from ? to : from;

        synchronized (first.getLock()) {
            synchronized (second.getLock()) {
                from.debitInternal(amount);    // debit without its own lock (already held)
                to.creditInternal(amount);     // credit without its own lock (already held)
            }
        }
    }
}
// WHY consistent order?
// Thread-1: transfer(Rajesh→Priya) → lock(Rajesh) → lock(Priya)
// Thread-2: transfer(Priya→Rajesh) → lock(Priya) → lock(Rajesh) ← DEADLOCK!
// FIX: both threads lock alphabetically: Priya first, then Rajesh (or by ID)
// Thread-1: lock(CUR3001/Priya) → lock(SAV2001/Rajesh)
// Thread-2: lock(CUR3001/Priya) → waits → gets it → lock(SAV2001/Rajesh)
// NO DEADLOCK!

// ═══ AVOID GLOBAL LOCK — kills parallelism ═══
// (Avoid) BAD: one lock for ALL accounts
// private static final Object GLOBAL_LOCK = new Object();
// synchronized(GLOBAL_LOCK) { account.debit(amount); }
// 10K accounts, 1 lock → sequential! Only 1 operation at a time for ALL accounts!

// (Recommended) GOOD: per-account lock
// synchronized(account.getLock()) { account.debit(amount); }
// 10K accounts, 10K locks → 10K parallel operations! One lock per account.
