package com.bank.concurrent;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class ConcurrentBankingTest {

    static class Account {
        private final String id;
        private final Object lock = new Object();
        private BigDecimal balance;

        Account(String id, BigDecimal balance) { this.id = id; this.balance = balance; }

        void debit(BigDecimal amount) {
            synchronized (lock) {
                if (balance.compareTo(amount) < 0)
                    throw new RuntimeException("Insufficient: " + id);
                balance = balance.subtract(amount);
            }
        }

        void credit(BigDecimal amount) {
            synchronized (lock) { balance = balance.add(amount); }
        }

        BigDecimal getBalance() {
            synchronized (lock) { return balance; }
        }

        String getId() { return id; }
        Object getLock() { return lock; }
    }

    static void transfer(Account from, Account to, BigDecimal amount) {
        // Consistent lock ordering by account ID — prevents deadlock!
        Account first = from.getId().compareTo(to.getId()) < 0 ? from : to;
        Account second = first == from ? to : from;

        synchronized (first.getLock()) {
            synchronized (second.getLock()) {
                if (from.balance.compareTo(amount) < 0)
                    throw new RuntimeException("Insufficient funds");
                from.balance = from.balance.subtract(amount);
                to.balance = to.balance.add(amount);
            }
        }
    }

    // ═══ Concurrent debits on SAME account — thread-safe ═══
    @Test
    void concurrentDebits_sameAccount() throws InterruptedException {
        Account rajesh = new Account("SAV2001", new BigDecimal("100000"));
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                rajesh.debit(new BigDecimal("1000"));
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(rajesh.getBalance()).isEqualByComparingTo("0");  // exact!
    }

    // ═══ Operations on DIFFERENT accounts — parallel ═══
    @Test
    void differentAccounts_parallel() throws InterruptedException {
        Account rajesh = new Account("SAV2001", new BigDecimal("100000"));
        Account priya = new Account("CUR3001", new BigDecimal("100000"));
        CountDownLatch latch = new CountDownLatch(2);

        long start = System.currentTimeMillis();
        new Thread(() -> {
            for (int i = 0; i < 1000; i++) rajesh.debit(new BigDecimal("100"));
            latch.countDown();
        }).start();

        new Thread(() -> {
            for (int i = 0; i < 1000; i++) priya.debit(new BigDecimal("100"));
            latch.countDown();
        }).start();

        latch.await();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(rajesh.getBalance()).isEqualByComparingTo("0");
        assertThat(priya.getBalance()).isEqualByComparingTo("0");
        // Both accounts processed in PARALLEL — different locks!
    }

    // ═══ Transfer — deadlock-free with consistent ordering ═══
    @Test
    void transfer_deadlockFree() throws InterruptedException {
        Account rajesh = new Account("SAV2001", new BigDecimal("100000"));
        Account priya = new Account("CUR3001", new BigDecimal("100000"));
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads * 2);

        // 50 threads: Rajesh → Priya
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                transfer(rajesh, priya, new BigDecimal("1000"));
                latch.countDown();
            }).start();
        }

        // 50 threads: Priya → Rajesh (OPPOSITE direction!)
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                transfer(priya, rajesh, new BigDecimal("1000"));
                latch.countDown();
            }).start();
        }

        latch.await(10, TimeUnit.SECONDS);

        // Total money conserved: 200,000 (100K + 100K)
        BigDecimal total = rajesh.getBalance().add(priya.getBalance());
        assertThat(total).isEqualByComparingTo("200000");
    }
}
